#include <iostream>
using namespace std;

struct Base {
    virtual string name() const { return "Base"; }
    string plain() const { return "Base"; }
    virtual ~Base() = default;
};
struct Derived : Base {
    string name() const override { return "Derived"; }
    string plain() const { return "Derived"; }
};

void byValue(Base b) { cout << b.name() << "\n"; }
void byRef(const Base& b) { cout << b.name() << "\n"; }

int main() {
    Derived d;
    Base* p = &d;
    cout << p->name() << "\n";
    cout << p->plain() << "\n";
    byValue(d);
    byRef(d);
    return 0;
}

#include <iostream>
using namespace std;

int next_id() {
    static int id = 0;
    return ++id;
}

struct Noisy {
    string label;
    Noisy(string l) : label(l) { cout << "make " << label << "\n"; }
    ~Noisy() { cout << "drop " << label << "\n"; }
};

int main() {
    cout << next_id() << "\n";
    cout << next_id() << "\n";
    {
        Noisy a("a");
        Noisy b("b");
    }
    cout << "after\n";
    cout << next_id() << "\n";
    return 0;
}

